import{j as e}from"./motion-C-3mcZ-r.js";import{L as o}from"./LegalPage-CEB1K7QO.js";import"./react-DgPQ2tCQ.js";import"./PageHero-C_CXnvih.js";import"./index-B-eiNqx5.js";const t=[{heading:"The short version",paragraphs:["This website does not collect or store anything about you. There is no account, no database behind it, and no form that sends data to us.","The contact form on this site does not submit anywhere. It takes what you type and opens WhatsApp with the message already written, so you can read it and decide whether to send. Until you press send in WhatsApp, nothing leaves your phone."]},{heading:"What happens when you contact us",paragraphs:["If you call, WhatsApp or email us, we keep what you tell us so we can answer you — your name, your village, your crop and the problem you described. We use it to give you guidance and nothing else.","We do not sell, rent or share your details with anybody outside Soil Charger Technology and its appointed distributors, and we do not add you to a marketing list without your asking."]},{heading:"Third-party services on this site",paragraphs:["Fonts are loaded from Google Fonts, which means Google receives the request for them — including your IP address — in the ordinary way any website font works.","The language switcher uses Google Translate. When you switch to Marathi or Hindi, the page content is sent to Google's translation service so it can be translated, and Google sets a cookie to remember your choice.","WhatsApp and phone links hand you over to those apps, which have their own privacy terms."]},{heading:"Cookies",paragraphs:["This site sets no cookies of its own. The only cookie you may end up with is the one Google Translate sets to remember your chosen language, and it is set only if you use the switcher."]},{heading:"Your choices",paragraphs:["You can ask us what we hold about you, ask us to correct it, or ask us to delete it. Call or write to us and we will do it."]}];function h(){return e.jsx(o,{kind:"privacy",title:"Privacy Policy",lead:"What this website does and does not do with your information, in plain language.",sections:t})}export{h as default};
